<script setup lang="ts">
import {computed,nextTick,onMounted,onUnmounted,reactive,ref,watch} from 'vue';
import Icon from './Icon.vue';
import CustomerPicker from './CustomerPicker.vue';
type Request=<T>(path:string,method?:string,body?:unknown,headers?:Record<string,string>)=>Promise<T>;
type Item={id:string;[key:string]:any};
type Delivery={reports:boolean;export:boolean;customerImport:boolean;attachmentRead:boolean;attachmentWrite:boolean};
type Business={contactRead:boolean;leads:{read:boolean};opportunities:{read:boolean};tasks:{read:boolean};activityRead:boolean};
const props=withDefaults(defineProps<{section:string;request:Request;download:(path:string,name:string)=>Promise<void>;access:Delivery;business:Business;customerRead:boolean;readonly:boolean;memberId?:string;customerId?:string}>(),{customerId:''});
const emit=defineEmits<{clearFilter:[];customer:[id:string];navigate:[section:string]}>();
const busy=ref(false),error=ref(''),success=ref(''),rows=ref<Item[]>([]),report=ref<any>(null),operations=ref<any>(null),unread=ref(0),page=ref(1),total=ref(0),q=ref('');
const today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Shanghai'}).format(new Date());
const dateFrom=ref(new Date(Date.now()-29*86400000).toISOString().slice(0,10)),dateTo=ref(today());
const exchangeTab=ref(props.access.export?'export':'import'),exportModule=ref('customers'),exportStatus=ref('');
const owners=ref<{id:string;name:string}[]>([]),owner=ref(''),csvFile=ref<File|null>(null),batch=ref<any>(null),selected=ref<number[]>([]),requestKey=ref('');
const dialog=ref(''),modal=ref<HTMLElement|null>(null),removeTarget=ref<Item|null>(null),uploadFile=ref<File|null>(null);
const form=reactive({customerId:'',customerName:'',opportunityId:''}),opportunities=ref<Item[]>([]),opPage=ref(1),opTotal=ref(0),opQuery=ref('');
const titles:Record<string,string>={reports:'真实数据报表',exchange:'导入与导出',attachments:'客户附件',notifications:'站内提醒','platform-operations':'平台运维'};
const modules=computed(()=>[{id:'customers',name:'客户',show:props.customerRead},{id:'contacts',name:'联系人',show:props.business.contactRead},{id:'leads',name:'线索',show:props.business.leads.read},{id:'opportunities',name:'商机',show:props.business.opportunities.read&&props.customerRead},{id:'tasks',name:'待办',show:props.business.tasks.read},{id:'activities',name:'跟进',show:props.business.activityRead}].filter(m=>m.show));
const jobNames:Record<string,string>={DATABASE_BACKUP:'加密数据库备份',BACKUP_RETENTION:'过期备份清理',REMINDERS:'待办提醒与附件清理',RECOVERY_MAIL:'密码找回邮件'};
const jobStatuses:Record<string,string>={SUCCESS:'成功',FAILED:'失败',RUNNING:'执行中'};
const stageNames:Record<string,string>={CONTACT:'初次接触',NEEDS:'需求确认',SOLUTION:'方案讨论',NEGOTIATION:'报价谈判',READY:'签约准备',WON:'成交',LOST:'丢单'};
const statuses=computed(()=>exportModule.value==='leads'?{NEW:'新线索',CONTACTED:'已联系',QUALIFIED:'合格',UNQUALIFIED:'不合格',CONVERTED:'已转客户'}:exportModule.value==='opportunities'?stageNames:exportModule.value==='tasks'?{PENDING:'未完成',DONE:'已完成',OVERDUE:'已逾期'}:{});
const pipeline=computed(()=>Object.entries(stageNames).map(([stage,name])=>({stage,name,...(report.value?.pipeline?.find((x:any)=>x.stage===stage)??{count:0,amountCents:0})})));
const maxCount=computed(()=>Math.max(1,...pipeline.value.map(x=>Number(x.count))));
function money(cents:number){return '¥'+(Number(cents)/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});}
function size(bytes:number){return bytes>=1073741824?(bytes/1073741824).toFixed(2)+' GB':bytes>=1048576?(bytes/1048576).toFixed(2)+' MB':bytes>=1024?(bytes/1024).toFixed(1)+' KB':bytes+' B';}
function date(value:string){return value?new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',dateStyle:'short',timeStyle:'short'}).format(new Date(value)):'—';}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn();}catch(e){const f=e as Error&{status?:number};error.value=f.message||'操作未完成';if([401,403,404].includes(f.status??0)){rows.value=[];batch.value=null;report.value=null;operations.value=null;dialog.value='';}}finally{busy.value=false;}}
async function load(){
 if(props.section==='reports')report.value=await props.request(`/reports/sales?from=${dateFrom.value}&to=${dateTo.value}`);
 else if(props.section==='exchange'){if(props.access.customerImport){rows.value=await props.request('/imports/customers');owners.value=await props.request('/customers/owners');if(!owners.value.some(m=>m.id===owner.value))owner.value=owners.value.find(m=>m.id===props.memberId)?.id??owners.value[0]?.id??'';}}
 else if(props.section==='attachments'){const result=await props.request<any>(`/attachments?page=${page.value}&pageSize=20&q=${encodeURIComponent(q.value)}${props.customerId?'&customerId='+props.customerId:''}`);rows.value=result.items;total.value=result.total;}
 else if(props.section==='notifications'){const result=await props.request<any>('/notifications');rows.value=result.items;unread.value=result.unread;}
 else operations.value=await props.request('/platform/operations');
}
function search(){page.value=1;return run(load);}
function turn(delta:number){page.value+=delta;return run(load);}
async function exportData(){return run(async()=>{const query=new URLSearchParams({q:q.value,status:exportStatus.value});await props.download('/exports/'+exportModule.value+'?'+query.toString(),'CRM-'+exportModule.value+'.csv');success.value='已按当前权限生成 CSV 文件';});}
function changeOwner(){batch.value=null;requestKey.value=crypto.randomUUID();}
function chooseCsv(event:Event){csvFile.value=(event.target as HTMLInputElement).files?.[0]??null;batch.value=null;selected.value=[];requestKey.value=crypto.randomUUID();}
function preview(){return run(async()=>{if(!csvFile.value||csvFile.value.size>524288)throw new Error('请选择512KB以内的UTF-8 CSV文件');const bytes=new Uint8Array(await csvFile.value.arrayBuffer());let text='';for(let i=0;i<bytes.length;i+=16384)text+=String.fromCharCode(...bytes.slice(i,i+16384));batch.value=await props.request('/imports/customers/preview','POST',{fileName:csvFile.value.name,csvBase64:btoa(text),ownerMemberId:owner.value},{'Idempotency-Key':requestKey.value});selected.value=batch.value.rows.filter((r:any)=>!r.errors.length).map((r:any)=>r.number);await load();});}
function showBatch(item:Item){return run(async()=>{batch.value=await props.request('/imports/customers/'+item.id);selected.value=batch.value.rows.filter((r:any)=>!r.errors.length).map((r:any)=>r.number);});}
function commit(){return run(async()=>{if(!batch.value||!selected.value.length)throw new Error('请选择至少一行通过预校验的客户');const commitKey='commit:'+batch.value.id+':'+batch.value.version+':'+[...selected.value].sort((a,b)=>a-b).join('-');batch.value=await props.request('/imports/customers/'+batch.value.id+'/commit','POST',{expectedVersion:batch.value.version,rowNumbers:selected.value},{'Idempotency-Key':commitKey.length<=100?commitKey:'commit:'+batch.value.id});await load();success.value='所选客户已全部入库';});}
function read(item:Item){return run(async()=>{await props.request('/notifications/'+item.id+'/read','POST');await load();});}
function openUpload(){return run(async()=>{form.customerId=props.customerId;form.opportunityId='';form.customerName='';uploadFile.value=null;opportunities.value=[];opPage.value=1;opTotal.value=0;opQuery.value='';requestKey.value=crypto.randomUUID();if(props.customerId)form.customerName=(await props.request<any>('/customers/'+props.customerId)).name;dialog.value='upload';if(form.customerId)await choices();});}
async function choices(){if(!form.customerId||!props.business.opportunities.read)return;const r=await props.request<any>(`/opportunities?customerId=${form.customerId}&q=${encodeURIComponent(opQuery.value)}&page=${opPage.value}&pageSize=20`);opportunities.value=r.items.filter((o:Item)=>o.canLink);opTotal.value=r.total;}
function chooseCustomer(id:string){form.customerId=id;form.customerName='';form.opportunityId='';opPage.value=1;opQuery.value='';run(choices);}
function choiceTurn(delta:number){opPage.value+=delta;return run(choices);}
function upload(){return run(async()=>{if(!uploadFile.value||uploadFile.value.size>5242880)throw new Error('请选择5MB以内的文件');const input=new FormData();input.set('customerId',form.customerId);if(form.opportunityId)input.set('opportunityId',form.opportunityId);input.set('file',uploadFile.value);await props.request('/attachments','POST',input,{'Idempotency-Key':requestKey.value});dialog.value='';await load();success.value='附件已保存到云端';});}
function openRemove(item:Item){removeTarget.value=item;dialog.value='remove';}
function remove(){return run(async()=>{if(!removeTarget.value)return;await props.request(`/attachments/${removeTarget.value.id}?expectedVersion=${removeTarget.value.version}`,'DELETE');dialog.value='';removeTarget.value=null;await load();success.value='附件已移除，无法再从工作区下载';});}
function job(){return run(async()=>{const result=await props.request<any>('/platform/jobs/reminders/run','POST');await load();if(result.status==='FAILED')throw new Error('部分任务未完成，失败原因已记录，待重试');success.value='提醒与附件清理任务已执行';});}
let previousFocus:HTMLElement|null=null,previousOverflow:string|null=null;
function restoreScroll(){if(previousOverflow!==null){document.body.style.overflow=previousOverflow;previousOverflow=null;}}
function close(){if(!busy.value)dialog.value='';}
watch(dialog,async value=>{if(value){previousFocus=document.activeElement as HTMLElement;if(previousOverflow===null)previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';await nextTick();modal.value?.querySelector<HTMLElement>('button:not(:disabled),input:not(:disabled)')?.focus({preventScroll:true});}else{restoreScroll();previousFocus?.focus({preventScroll:true});}});
function keys(e:KeyboardEvent){if(!dialog.value)return;if(e.key==='Escape')close();if(e.key==='Tab'){const all=modal.value?.querySelectorAll<HTMLElement>('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled)');if(!all?.length)return;const first=all[0],last=all[all.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
onMounted(()=>document.addEventListener('keydown',keys));onUnmounted(()=>{document.removeEventListener('keydown',keys);restoreScroll();});
watch(()=>[props.section,props.customerId],()=>{page.value=1;q.value='';success.value='';batch.value=null;rows.value=[];report.value=null;operations.value=null;run(load);},{immediate:true});
watch(exportModule,()=>{exportStatus.value='';});
</script>
<template>
 <section class="delivery-workspace"><div class="page-heading"><div><span class="eyebrow">{{section==='platform-operations'?'PLATFORM OPERATIONS':'YOUR CRM DATA'}}</span><h1>{{titles[section]}}</h1><p>{{section==='reports'?'基于真实业务和当前访问权限，查看客户经营进展。':section==='exchange'?'先核对数据，再导入；导出仅包含当前可见资料。':section==='attachments'?'为客户和商机保留相关文件，下载时重新检查权限。':section==='notifications'?'查看属于你的到期与逾期待办提醒。':'检查应用、数据库、附件服务和后台任务状态。'}}</p></div><button class="btn secondary" :disabled="busy" @click="run(load)"><Icon name="refresh" :size="17"/>刷新</button><button v-if="section==='attachments'&&access.attachmentWrite&&!readonly" class="btn primary" :disabled="busy" @click="openUpload"><Icon name="plus" :size="17"/>上传附件</button></div>
  <div v-if="error&&!dialog" class="delivery-alert error" role="alert">{{error}}</div><div v-if="success" class="delivery-alert ok" role="status">{{success}}</div>
  <template v-if="section==='reports'"><form class="card delivery-toolbar" @submit.prevent="run(load)"><label>开始日期<input v-model="dateFrom" type="date" required/></label><label>结束日期<input v-model="dateTo" type="date" required/></label><button class="btn primary" :disabled="busy">查看统计</button><small>最多366天 · 上海时区</small></form><template v-if="report"><div class="delivery-summary"><article v-if="report.customers!=null" class="card"><span>本期新增客户</span><strong>{{report.customers}}</strong></article><article v-if="report.leads" class="card"><span>本期创建线索 / 已转换</span><strong>{{report.leads.total}} <small>/ {{report.leads.converted}}</small></strong></article><article v-if="report.won" class="card"><span>本期实际成交金额</span><strong>{{money(report.won.amountCents)}}</strong><small>{{report.won.count}} 项成交商机</small></article><article v-if="report.activities!=null" class="card"><span>本期客户跟进</span><strong>{{report.activities}}</strong></article></div><div class="delivery-columns"><section v-if="business.opportunities.read&&customerRead" class="card delivery-block"><h2>本期创建商机的当前阶段</h2><div v-for="p in pipeline" :key="p.stage" class="delivery-chart-row"><span>{{p.name}}</span><div><i :style="{width:(Number(p.count)/maxCount*100)+'%'}"></i></div><b>{{p.count}}</b><small>{{money(p.amountCents)}}</small></div><p class="delivery-muted">阶段金额为预计金额；上方成交金额按本期实际成交时间统计。</p></section><section class="card delivery-block"><h2>线索与跟进效率</h2><div v-if="report.leads" class="delivery-stat"><span>本期线索转化率</span><strong>{{report.leads.total?(report.leads.converted/report.leads.total*100).toFixed(1):'0.0'}}%</strong><small>本期创建线索中，当前已转客户的比例</small></div><div v-if="report.tasks" class="delivery-stat"><span>本期截止待办：完成 / 总数</span><strong>{{report.tasks.done}} / {{report.tasks.total}}</strong><small>其中 {{report.tasks.overdue}} 项当前逾期</small></div><div v-for="s in report.leadSources" :key="s.source" class="delivery-source"><span>{{s.source}}</span><b>{{s.count}}</b></div></section></div></template></template>
  <template v-else-if="section==='exchange'"><div class="delivery-tabs"><button v-if="access.export" :class="{active:exchangeTab==='export'}" @click="exchangeTab='export'">权限范围内导出</button><button v-if="access.customerImport" :class="{active:exchangeTab==='import'}" @click="exchangeTab='import'">客户批量导入</button></div><section v-if="exchangeTab==='export'" class="card delivery-block"><h2>导出业务资料</h2><form class="delivery-form" @submit.prevent="exportData"><label>数据类型<select v-model="exportModule"><option v-for="m in modules" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>搜索范围<input v-model="q" maxlength="100" placeholder="与业务列表的搜索条件一致"/></label><label v-if="Object.keys(statuses).length">状态 / 阶段<select v-model="exportStatus"><option value="">全部</option><option v-for="(name,value) in statuses" :key="value" :value="value">{{name}}</option></select></label><button class="btn primary" :disabled="busy">下载 CSV</button></form><p class="delivery-muted">最多5000行，字段按当前权限隐藏；CSV 对公式起始字符作文本处理。导出动作会记入审计。</p></section><template v-else><section class="card delivery-block"><div class="delivery-row"><h2>先预校验，再确认入库</h2><button class="btn secondary" :disabled="busy" @click="run(()=>download('/imports/customers/template','客户导入模板.csv'))">下载模板</button></div><p class="delivery-muted">UTF-8 CSV，最多512KB和500条客户；保留七列表头顺序。一个批次使用同一客户负责人，24小时内确认。</p><form class="delivery-form" @submit.prevent="preview"><label>客户负责人<select v-model="owner" required :disabled="busy||readonly" @change="changeOwner"><option value="">请选择负责人</option><option v-for="m in owners" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label>CSV 文件<input type="file" accept=".csv,text/csv" :disabled="busy||readonly" @change="chooseCsv"/></label><button class="btn primary" :disabled="busy||readonly||!csvFile">预校验</button></form></section><section v-if="batch" class="card delivery-block"><div class="delivery-row"><h2>{{batch.fileName}}</h2><span class="badge neutral">{{batch.status==='COMMITTED'?'已入库':'预校验'}} · {{batch.readyCount}} 行可导入</span></div><div class="table-scroll"><table><thead><tr><th>选择</th><th>行号</th><th>客户</th><th>行业 / 等级</th><th>校验结果</th></tr></thead><tbody><tr v-for="r in batch.rows" :key="r.number"><td><input v-model="selected" type="checkbox" :value="r.number" :disabled="busy||readonly||!batch.canCommit||!!r.errors.length" :aria-label="'选择第'+r.number+'行'"/></td><td>{{r.number}}<small>文件第 {{r.line}} 行</small></td><td>{{r.name}}</td><td>{{r.industry}} / {{r.level}}</td><td><span v-if="!r.errors.length" class="badge green">通过</span><span v-else class="delivery-danger">{{r.errors.join('；')}}</span></td></tr></tbody></table></div><div class="delivery-row"><p class="delivery-muted">所选行一起入库，任何失败都会全部回滚；已完成批次不能重复入库。</p><button v-if="batch.canCommit" class="btn primary" :disabled="busy||readonly||!selected.length" @click="commit">确认导入 {{selected.length}} 行</button></div><div v-if="batch.createdCustomers?.length" class="delivery-links"><button v-for="c in batch.createdCustomers" :key="c.id" class="text-button" @click="emit('customer',c.id)">{{c.name}}</button></div></section><section class="card delivery-block"><h2>我的最近导入批次</h2><div v-for="b in rows" :key="b.id" class="delivery-history"><button class="text-button" :disabled="busy" @click="showBatch(b)">{{b.fileName}}</button><span>{{b.status==='COMMITTED'?'已入库':'待确认'}} · {{date(b.createdAt)}}</span></div><p v-if="!rows.length" class="delivery-muted">还没有导入批次</p></section></template></template>
  <template v-else-if="section==='attachments'"><div v-if="customerId" class="delivery-filter"><span>此客户的附件</span><button class="text-button" :disabled="busy" @click="emit('clearFilter')">查看全部</button></div><form class="delivery-toolbar" @submit.prevent="search"><input v-model="q" maxlength="100" placeholder="搜索文件名或客户" aria-label="搜索附件"/><button class="btn secondary" :disabled="busy">搜索</button><span>共 {{total}} 项</span></form><section class="card delivery-table"><div class="table-scroll"><table><thead><tr><th>文件</th><th>客户 / 商机</th><th>大小</th><th>上传人</th><th>上传时间</th><th>操作</th></tr></thead><tbody><tr v-for="f in rows" :key="f.id"><td><strong>{{f.fileName}}</strong><small>{{f.contentType}}</small></td><td>{{f.customerName}}<small>{{f.opportunityTitle||'客户资料'}}</small></td><td>{{size(f.sizeBytes)}}</td><td>{{f.uploaderName}}</td><td>{{date(f.createdAt)}}</td><td><div class="delivery-actions"><button class="text-button" :disabled="busy" @click="run(()=>download('/attachments/'+f.id+'/download',f.fileName))">下载</button><button v-if="f.canWrite&&!readonly" class="text-button delivery-danger" :disabled="busy" @click="openRemove(f)">删除</button></div></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty-cell">{{busy?'正在加载…':'暂无可见附件'}}</td></tr></tbody></table></div><footer class="delivery-pagination"><span>第 {{page}} 页</span><button class="btn secondary" :disabled="busy||page<=1" @click="turn(-1)">上一页</button><button class="btn secondary" :disabled="busy||page*20>=total" @click="turn(1)">下一页</button></footer></section><p class="delivery-muted">单个文件最多5MB，支持 PNG、JPEG、PDF、UTF-8 TXT / CSV。文件通过当前权限检查后下载。</p></template>
  <template v-else-if="section==='notifications'"><section class="card delivery-block"><div class="delivery-row"><h2>我的待办提醒</h2><span class="badge neutral">{{unread}} 条未读</span></div><article v-for="n in rows" :key="n.id" class="delivery-notification"><span class="badge" :class="n.kind==='OVERDUE'?'orange':'green'">{{n.kind==='OVERDUE'?'逾期':'今日到期'}}</span><div><strong>{{n.title}}</strong><p>截止 {{n.dueDate}} · {{date(n.createdAt)}}</p></div><button v-if="!n.readAt" class="text-button" :disabled="busy" @click="read(n)">标为已读</button><span v-else class="delivery-muted">已读</span><button class="text-button" @click="emit('navigate','tasks')">打开待办</button></article><p v-if="!rows.length" class="delivery-muted">暂无当前可见提醒。任务完成、转交或权限变化后，提醒会重新过滤。</p></section><p class="delivery-muted">后台约每5分钟检查一次。每个任务版本每天生成一条对应提醒，不重复发送。此处为站内提醒。</p></template>
  <template v-else-if="operations"><div v-if="operations.jobs.some((j:any)=>j.status==='FAILED')" class="delivery-alert error" role="alert">最近有任务失败，请查看下方错误编号和后续重试结果。</div><div class="delivery-summary"><article class="card"><span>应用版本 / 运行时间</span><strong>v{{operations.version}}</strong><small>{{Math.floor(operations.uptimeSeconds/60)}} 分钟</small></article><article class="card"><span>数据库</span><strong>{{operations.database.status}}</strong><small>{{operations.database.latencyMs}} ms</small></article><article class="card"><span>附件服务</span><strong>{{operations.storage.healthy?'正常':operations.storage.configured?'待检查':'未配置'}}</strong></article><article class="card"><span>提醒任务</span><strong>{{operations.reminderScheduleEnabled?'已启用':'未启用'}}</strong><button class="text-button" :disabled="busy" @click="job">立即检查提醒与清理</button></article></div><section class="card delivery-block"><h2>资源状态</h2><p class="delivery-muted">堆内存 {{size(operations.heap.usedBytes)}} / {{size(operations.heap.maxBytes)}}；数据库连接：活跃 {{operations.connections?.active??'—'}}，空闲 {{operations.connections?.idle??'—'}}，等待 {{operations.connections?.waiting??'—'}}。</p><h2>备份与保留规则</h2><p class="delivery-muted">每天北京时间 02:00 运行加密备份和独立恢复校验。保留 30 天，并保护最近 3 份成功备份；新快照通过恢复验证后才清理过期文件。密钥由独立备份服务保管，离线保管交接待完成。</p><h2>最近任务记录</h2><div class="table-scroll"><table><thead><tr><th>任务</th><th>状态</th><th>开始 / 结束</th><th>处理数量</th><th>结果</th></tr></thead><tbody><tr v-for="j in operations.jobs" :key="j.id"><td>{{jobNames[j.jobName]??j.jobName}}<small>{{j.jobName}}</small></td><td><span class="badge" :class="j.status==='SUCCESS'?'green':j.status==='FAILED'?'orange':'neutral'">{{jobStatuses[j.status]??j.status}}</span></td><td>{{date(j.startedAt)}}<small>{{date(j.finishedAt)}}</small></td><td>{{j.processedCount}}</td><td>{{j.errorCode||'—'}}<small v-if="j.artifactBytes">备份 {{size(j.artifactBytes)}} · 校验 {{j.artifactSha256?.slice(0,12)}}<br/>{{j.artifactAvailable?'恢复文件已保留':'恢复文件已清理，审计记录保留'}}</small></td></tr><tr v-if="!operations.jobs.length"><td colspan="5" class="empty-cell">暂无任务记录</td></tr></tbody></table></div><p class="delivery-muted">运维页面只展示状态和任务摘要，不展示客户业务正文、存储凭据或备份下载地址。</p></section></template>
  <Teleport to="body"><div v-if="dialog" class="modal-backdrop" @click.self="close"><section ref="modal" class="delivery-dialog" role="dialog" aria-modal="true" aria-labelledby="delivery-dialog-title"><header><h2 id="delivery-dialog-title">{{dialog==='upload'?'上传客户附件':'删除附件'}}</h2><button class="icon-button" :disabled="busy" aria-label="关闭附件窗口" @click="close"><Icon name="close"/></button></header><form @submit.prevent="dialog==='upload'?upload():remove()"><div class="delivery-dialog-body"><template v-if="dialog==='upload'"><div class="delivery-field"><strong>所属客户</strong><CustomerPicker :model-value="form.customerId" :request="request" :selected-name="form.customerName" :disabled="busy" @update:model-value="chooseCustomer"/></div><div v-if="form.customerId&&business.opportunities.read" class="delivery-field"><strong>关联商机（可选）</strong><div class="delivery-choice"><input v-model="opQuery" aria-label="查找所属客户商机" maxlength="100" placeholder="查找商机" @keydown.enter.prevent="opPage=1;run(choices)"/><button type="button" class="btn secondary" :disabled="busy" @click="opPage=1;run(choices)">查找</button></div><select v-model="form.opportunityId" :disabled="busy"><option value="">只关联客户</option><option v-for="o in opportunities" :key="o.id" :value="o.id">{{o.title}}</option></select><div class="delivery-row delivery-muted"><span>第 {{opPage}} 页</span><button type="button" :disabled="busy||opPage<=1" @click="choiceTurn(-1)">上一页</button><button type="button" :disabled="busy||opPage*20>=opTotal" @click="choiceTurn(1)">下一页</button></div></div><label class="delivery-field">选择文件<input type="file" accept=".png,.jpg,.jpeg,.pdf,.txt,.csv" required :disabled="busy" @change="uploadFile=($event.target as HTMLInputElement).files?.[0]??null"/></label><p class="delivery-muted">保存时检查文件格式、客户 / 商机权限及套餐附件容量。</p></template><template v-else><strong>{{removeTarget?.fileName}}</strong><p class="delivery-muted">删除后，此文件将不再可下载。该操作不会删除客户或商机。</p></template><div v-if="error" class="delivery-alert error" role="alert">{{error}}</div></div><footer><button type="button" class="btn secondary" :disabled="busy" @click="close">取消</button><button class="btn primary" :disabled="busy||dialog==='upload'&&(!uploadFile||!form.customerId)">{{busy?'正在处理…':dialog==='upload'?'保存附件':'确认删除'}}</button></footer></form></section></div></Teleport>
 </section>
</template>
